// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 blockNumber, uint256 blockTimestamp) public {
        // Restrict block.number to avoid triggering the transfer (which alters balance)
        vm.assume(blockNumber % 15 != 0);

        // Ensure the call will succeed: require(block.timestamp > pastBlockTime)
        vm.assume(blockTimestamp > c.pastBlockTime());

        // Set block parameters
        vm.roll(blockNumber);
        vm.warp(blockTimestamp);

        // Provide exactly 10 ether
        vm.deal(address(this), 10 ether);

        // Call fallback
        (bool success, ) = address(c).call{value: 10 ether}("");

        // Rule: if call succeeded and no transfer occurred, pastBlockTime == block.timestamp
        uint expectedPastBlockTime = block.timestamp;
        assertTrue(!success || c.pastBlockTime() == expectedPastBlockTime);
    }
}

